<?php declare(strict_types=1); namespace App\Domains\WorkCore\System\Modules\Reviews\Actions; use App\Domains\WorkCore\System\Actions\{ActionHandlerResult,ActionRequest,PendingDomainEvent}; use App\Domains\WorkCore\System\Actions\Contracts\BusinessActionHandlerContract; use App\Domains\WorkCore\System\Modules\Reviews\Contracts\ReviewRepositoryContract; use App\Domains\WorkCore\System\References\TypedReference; final class CreateServiceRecovery implements BusinessActionHandlerContract { public function __construct(private ReviewRepositoryContract $repository){} public function handle(ActionRequest $r): ActionHandlerResult {$x=$this->repository->createRecovery((string)$r->payload['review_public_id'],$r->payload,$r->companyId,$r->actorId);return new ActionHandlerResult($x,new TypedReference('service_recovery',(string)$x['public_id']),[new PendingDomainEvent('workcore.service_recovery.created',1,['case'=>$x])]);}}
